function csvGen(schema,n,seed){var r=rng2(seed||1);var rows=[schema.map(function(c){return c.name;}).join(',')];
for(var i=0;i<n;i++){rows.push(schema.map(function(c){return csvVal(c,r,i);}).join(','));}return rows.join('\n');}
function rng2(seed){var a=seed>>>0;return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function csvVal(c,r,i){if(c.type==='id')return i+1;if(c.type==='int')return c.min+Math.floor(r()*(c.max-c.min+1));
if(c.type==='name'){var ns=['Jo','Mara','Theo'];return ns[Math.floor(r()*ns.length)];}
if(c.type==='bool')return r()>0.5;return '';}
function csvParse(csv){return csv.split('\n').map(function(l){return l.split(',');});}
